import ifcopenshell as ifc
import ifcopenshell.geom
import numpy as np

f = ifc.open('output/model.ifc')
pipes = [x for x in f.by_type('IfcPipeSegment') if x.ObjectType == 'PIPE']
crahs = [x for x in f.by_type('IfcUnitaryEquipment') if x.ObjectType == 'CRAH']

settings = ifcopenshell.geom.settings()
settings.set(settings.USE_WORLD_COORDS, True)

def get_bbox(element):
    try:
        shape = ifcopenshell.geom.create_shape(settings, element)
        verts = shape.geometry.verts
        verts = np.array(verts).reshape(-1, 3) * 1000
        min_pt = verts.min(axis=0)
        max_pt = verts.max(axis=0)
        return min_pt, max_pt
    except Exception as e:
        return None, None

for c in crahs:
    mn, mx = get_bbox(c)
    if mn is not None:
        print(f'CRAH: bbox=({mn[0]:.0f},{mn[1]:.0f},{mn[2]:.0f})-({mx[0]:.0f},{mx[1]:.0f},{mx[2]:.0f})')

# Check specific CHW vertical drop pipes
for pipe in pipes:
    psets = [ps for ps in f.by_type('IfcRelDefinesByProperties') if pipe in ps.RelatedObjects]
    for ps in psets:
        if ps.RelatingPropertyDefinition.Name == 'Pset_DCM_CHW':
            props = {}
            for prop in ps.RelatingPropertyDefinition.HasProperties:
                if prop.NominalValue:
                    props[prop.Name] = prop.NominalValue.wrappedValue
            if 'SegmentIndex' in props and props['SegmentIndex'] in [31,32,34,36,38,40]:
                mn, mx = get_bbox(pipe)
                if mn is not None:
                    print(f'  CHW seg {props[\"SegmentIndex\"]}: bbox=({mn[0]:.0f},{mn[1]:.0f},{mn[2]:.0f})-({mx[0]:.0f},{mx[1]:.0f},{mx[2]:.0f})')
